import os
import subprocess
import tempfile
import hashlib
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import yaml

app = Flask(__name__)

REPORT_TEMPLATES_DIR = '/opt/reports/templates'
OUTPUT_DIR = '/tmp/reports'
ALLOWED_FORMATS = ['pdf', 'html', 'csv']

def load_config():
    config_path = os.environ.get('REPORT_CONFIG', '/etc/report-service/config.yaml')
    with open(config_path, 'r') as f:
        return yaml.safe_load(f)

def validate_template_name(name):
    """Basic template name validation"""
    if not name or len(name) > 64:
        return False
    if '..' in name:
        return False
    return True

def get_template_path(template_name):
    """Resolve template path - supports subdirectories for org separation"""
    base = REPORT_TEMPLATES_DIR
    full_path = os.path.join(base, template_name)
    # Normalize but allow subdirectories
    return os.path.normpath(full_path)

@app.route('/api/v1/reports/generate', methods=['POST'])
def generate_report():
    config = load_config()

    data = request.get_json()
    if not data:
        return jsonify({'error': 'JSON body required'}), 400

    template_name = data.get('template', '')
    output_format = data.get('format', 'pdf')
    parameters = data.get('parameters', {})

    if output_format not in ALLOWED_FORMATS:
        return jsonify({'error': f'Format must be one of {ALLOWED_FORMATS}'}), 400

    if not validate_template_name(template_name):
        return jsonify({'error': 'Invalid template name'}), 400

    template_path = get_template_path(template_name)
    if not os.path.exists(template_path):
        return jsonify({'error': 'Template not found'}), 404

    # Build report generation command
    output_file = os.path.join(
        OUTPUT_DIR, 
        f"{hashlib.md5(template_name.encode()).hexdigest()}_{os.getpid()}.{output_format}"
    )

    # The report engine supports variable substitution via --set key=value
    cmd = ['reportgen', '--template', template_path, '--output', output_file, '--format', output_format]

    for key, value in parameters.items():
        # Parameters are passed to the report engine
        cmd.extend(['--set', f'{key}={value}'])

    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            timeout=30,
            env={**os.environ, 'REPORT_LOCALE': data.get('locale', 'en_US')}
        )

        if result.returncode != 0:
            app.logger.error(f"Report generation failed: {result.stderr.decode()}")
            return jsonify({'error': 'Generation failed', 'detail': result.stderr.decode()[:200]}), 500

        return send_file(output_file, as_attachment=True)

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Report generation timed out'}), 504
    except Exception as e:
        app.logger.error(f"Unexpected error: {e}")
        return jsonify({'error': 'Internal error'}), 500

@app.route('/api/v1/reports/templates', methods=['GET'])
def list_templates():
    """List available templates"""
    templates = []
    for root, dirs, files in os.walk(REPORT_TEMPLATES_DIR):
        for f in files:
            rel = os.path.relpath(os.path.join(root, f), REPORT_TEMPLATES_DIR)
            templates.append(rel)
    return jsonify({'templates': templates})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
